selector_to_html = {"a[href=\"#lora\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">LoRA<a class=\"headerlink\" href=\"#lora\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#normalization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Normalization<a class=\"headerlink\" href=\"#normalization\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#quantization\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quantization<a class=\"headerlink\" href=\"#quantization\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#multi-backend-operator-coverage\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-backend operator coverage<a class=\"headerlink\" href=\"#multi-backend-operator-coverage\" title=\"Link to this heading\">#</a></h2><p>Beyond the generic implementations, vendors ship specializations under <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flaggems_sglang/runtime/backend/_&lt;vendor&gt;/ops/</span></code>. Per-vendor coverage counts are in the backends table in <a class=\"reference internal\" href=\"../overview/features.html\"><span class=\"std std-doc\">Features</span></a>. Operators a vendor does not specialize fall back to the generic Triton implementation.</p>", "a[href=\"#activation-and-gating\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Activation and Gating<a class=\"headerlink\" href=\"#activation-and-gating\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#attention\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attention<a class=\"headerlink\" href=\"#attention\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#operator-list\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h1><p>This page lists the operators exported by FlagGems-sglang, sourced from <code class=\"docutils literal notranslate\"><span class=\"pre\">conf/operators.yaml</span></code> and the <code class=\"docutils literal notranslate\"><span class=\"pre\">__all__</span></code> of <code class=\"docutils literal notranslate\"><span class=\"pre\">src/flaggems_sglang/ops/*.py</span></code>.</p><p>The generic operator set contains 40 operators, and the two sources agree name for name. Each operator is implemented in Triton and resolved for the current device by the three-level registrar described in <a class=\"reference internal\" href=\"../overview/overview.html\"><span class=\"std std-doc\">Overview</span></a>.</p>", "a[href=\"#chunked-cumulative-sum\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Chunked Cumulative Sum<a class=\"headerlink\" href=\"#chunked-cumulative-sum\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#mixture-of-experts-moe\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Mixture of Experts (MoE)<a class=\"headerlink\" href=\"#mixture-of-experts-moe\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#speculative-decoding\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Speculative Decoding<a class=\"headerlink\" href=\"#speculative-decoding\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../overview/features.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features<a class=\"headerlink\" href=\"#features\" title=\"Link to this heading\">#</a></h1><p>FlagGems-sglang provides the following key features:</p>", "a[href=\"#mamba-and-ssm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Mamba and SSM<a class=\"headerlink\" href=\"#mamba-and-ssm\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems-sglang Overview<a class=\"headerlink\" href=\"#flaggems-sglang-overview\" title=\"Link to this heading\">#</a></h1><p>FlagGems-sglang is part of <a class=\"reference external\" href=\"https://flagos.io/\">FlagOS</a>. It is a high-performance operator library designed for multiple hardware backends. It provides optimized implementations of common SGLang operators and supports high-performance inference and deployment for a variety of widely used models.</p><p>FlagGems-sglang is a high-performance deep learning operator library implemented using the <a class=\"reference external\" href=\"https://github.com/openai/triton\">Triton programming language</a> launched by OpenAI.</p>", "a[href=\"#sampling\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Sampling<a class=\"headerlink\" href=\"#sampling\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#rotary-positional-embedding\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Rotary Positional Embedding<a class=\"headerlink\" href=\"#rotary-positional-embedding\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
